{"file_path": "/designs/probe.py", "content": "import scadnano as sc

def try_top(o):
    # helix0 fwd ends at top o-1 (domain [0,o)); helix1 rev ends at top o-1 (domain [0,o))
    helices = [sc.Helix(max_offset=96, grid_position=(i, 0)) for i in range(2)]
    d = sc.Design(helices=helices, strands=[], grid=sc.square, geometry=sc.Geometry(bases_per_turn=10.67))
    d.draw_strand(0, 0).move(o).as_scaffold()
    d.draw_strand(1, o).move(-o)
    try:
        d.add_half_crossover(helix=0, helix2=1, offset=o, forward=True)
        return "ok"
    except Exception as e:
        return "ERR " + str(e)[:80]

def try_bottom(a):
    # helix1 rev ends at bottom a (domain [a,96)); helix2 fwd starts at bottom a
    helices = [sc.Helix(max_offset=96, grid_position=(i, 0)) for i in range(3)]
    d = sc.Design(helices=helices, strands=[], grid=sc.square, geometry=sc.Geometry(bases_per_turn=10.67))
    d.draw_strand(1, 96).move(-(96 - a)).as_scaffold()
    d.draw_strand(2, a).move(96 - a)
    try:
        d.add_half_crossover(helix=1, helix2=2, offset=a, forward=False)
        return "ok"
    except Exception as e:
        return "ERR " + str(e)[:80]

for o in range(84, 97):
    print("top", o, try_top(o))
for a in range(0, 12):
    print("bottom", a, try_bottom(a))
